using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

using SportsData.Core.Infrastructure.Data.Entities;

namespace SportsData.Api.Infrastructure.Data.Entities
{
    /// <summary>
    /// One finished mini-game (the football card game today). Generic on
    /// purpose: outcome and both scores are columns; anything game-specific
    /// goes in <see cref="Detail"/> until something needs to query it.
    /// <see cref="CanonicalEntityBase{T}.Id"/> is generated by the CLIENT when
    /// the game ends, so an offline device re-uploading the same result is a
    /// no-op. <see cref="CanonicalEntityBase{T}.CreatedUtc"/> is the server's
    /// receive time; <see cref="PlayedUtc"/> is the client's. Abandoned games
    /// are never recorded. See docs/features/mini-game-results.md.
    /// </summary>
    public class MiniGameResult : CanonicalEntityBase<Guid>
    {
        public const int GameKeyMaxLength = 32;
        public const int GameVersionMaxLength = 32;
        public const int SeedMaxLength = 64;

        public Guid UserId { get; set; }

        public User User { get; set; } = null!;

        public string GameKey { get; set; } = null!;

        public MiniGameOutcome Outcome { get; set; }

        public int Score { get; set; }

        public int OpponentScore { get; set; }

        public int DurationSeconds { get; set; }

        /// <summary>Engine + card-set version, so balance numbers split by version.</summary>
        public string GameVersion { get; set; } = null!;

        /// <summary>Shuffle seed; the engine is otherwise deterministic, so this enables replay.</summary>
        public string? Seed { get; set; }

        /// <summary>Game-specific extras as raw JSON. Empty in v1.</summary>
        public string? Detail { get; set; }

        public DateTime PlayedUtc { get; set; }

        public class EntityConfiguration : IEntityTypeConfiguration<MiniGameResult>
        {
            public void Configure(EntityTypeBuilder<MiniGameResult> builder)
            {
                builder.ToTable(nameof(MiniGameResult));

                builder.HasKey(x => x.Id);

                builder.Property(x => x.GameKey).IsRequired().HasMaxLength(GameKeyMaxLength);
                builder.Property(x => x.Outcome).HasConversion<short>().IsRequired();
                builder.Property(x => x.GameVersion).IsRequired().HasMaxLength(GameVersionMaxLength);
                builder.Property(x => x.Seed).HasMaxLength(SeedMaxLength);
                builder.Property(x => x.Detail).HasColumnType("jsonb");

                builder.HasIndex(x => new { x.UserId, x.GameKey, x.PlayedUtc });

                builder.HasOne(x => x.User)
                    .WithMany()
                    .HasForeignKey(x => x.UserId)
                    .OnDelete(DeleteBehavior.Cascade);
            }
        }
    }

    public enum MiniGameOutcome : short
    {
        Win = 1,
        Loss = 2,
        Tie = 3
    }
}
